import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { chromium } from 'playwright';
import { createClient } from '@supabase/supabase-js';

// Explicit integration check, invoked manually; never run by build or CI.
// Recreates only the disposable manager generated by provision-test-accounts.mjs,
// and only if it has never submitted a command or a daily sheet.
process.loadEnvFile('.env.local');
process.loadEnvFile('.env.server.local');
const accounts = JSON.parse(await readFile('.local/test-accounts.json', 'utf8'));
const admin = accounts.find(a => a.role === 'admin');
const manager = accounts.find(a => a.role === 'manager');
const service = createClient(process.env.VITE_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY, { auth: { persistSession: false, autoRefreshToken: false } });
const site = 'https://gestionbar-amber.vercel.app';
const browser = await chromium.launch();
const context = await browser.newContext();
const page = await context.newPage();
const errors = []; page.on('pageerror', e => errors.push(e.message));
async function signIn(page, account) {
  await page.goto(site);
  await page.getByLabel('Adresse e-mail', { exact: true }).fill(account.email);
  await page.getByLabel('Mot de passe', { exact: true }).fill(account.password);
  await page.getByRole('button', { name: 'Se connecter', exact: true }).click();
  await page.getByRole('heading', { name: 'Bonjour,' }).waitFor({ timeout: 20000 });
}
try {
  await signIn(page, admin);
  await page.getByRole('button', { name: 'Paramètres', exact: true }).click();
  await page.getByRole('button', { name: 'Comptes & rôles', exact: true }).click();
  await page.getByRole('button', { name: 'Créer un compte', exact: true }).waitFor();
  const unauthenticated = await page.request.post(site + '/api/accounts', { data: {} });
  assert.equal(unauthenticated.status(), 401);

  const { data: existing, error: existingError } = await service.auth.admin.getUserById(manager.id);
  if (existingError) throw new Error(existingError.message);
  assert.equal(existing.user.user_metadata.comptoir_test_account, true, 'Only the generated test manager can be recreated');
  for (const [table, column] of [['command_receipts', 'user_id'], ['daily_sheets', 'created_by']]) {
    const { count, error } = await service.from(table).select('id', { count: 'exact', head: true }).eq(column, manager.id);
    if (error) throw new Error(error.message);
    assert.equal(count, 0, 'Do not recreate a test user that has business history');
  }
  const { error: profileDeleteError } = await service.from('profiles').delete().eq('id', manager.id);
  if (profileDeleteError) throw new Error(profileDeleteError.message);
  const { error: authDeleteError } = await service.auth.admin.deleteUser(manager.id);
  if (authDeleteError) throw new Error(authDeleteError.message);

  await page.getByRole('button', { name: 'Créer un compte', exact: true }).click();
  const dialog = page.getByRole('dialog');
  await dialog.getByLabel('Nom de l’utilisateur').fill(manager.name);
  await dialog.getByLabel('Adresse e-mail de connexion').fill(manager.email);
  await dialog.getByLabel('Mot de passe', { exact: true }).fill(manager.password);
  await dialog.getByLabel('Rôle', { exact: true }).selectOption('manager');
  const responsePromise = page.waitForResponse(r => r.url().endsWith('/api/accounts') && r.request().method() === 'POST');
  await dialog.getByRole('button', { name: 'Créer le compte', exact: true }).click();
  const response = await responsePromise;
  const result = await response.json();
  assert.equal(response.status(), 201, result.error || 'Account creation failed');
  manager.id = result.id;
  await writeFile('.local/test-accounts.json', JSON.stringify(accounts, null, 2), { mode: 0o600 });
  const { error: markerError } = await service.auth.admin.updateUserById(manager.id, { user_metadata: { name: manager.name, comptoir_test_account: true } });
  if (markerError) throw new Error(markerError.message);
  await page.getByRole('row').filter({ hasText: manager.name }).waitFor();
  await page.screenshot({ path: 'test-results/production-accounts.png', fullPage: true });

  const managerContext = await browser.newContext();
  const managerPage = await managerContext.newPage();
  await signIn(managerPage, manager);
  assert.equal(await managerPage.getByRole('button', { name: 'Paramètres', exact: true }).count(), 0);
  const session = await managerPage.evaluate(() => Object.keys(localStorage).filter(k => k.endsWith('-auth-token')).map(k => JSON.parse(localStorage.getItem(k))).find(s => s?.access_token));
  assert.ok(session?.access_token);
  const forbidden = await managerPage.request.post(site + '/api/accounts', { headers: { Authorization: 'Bearer ' + session.access_token }, data: { name: 'Must not create', email: 'must-not-create@comptoir.example', password: manager.password, role: 'admin' } });
  assert.equal(forbidden.status(), 403);
  const salary = await managerPage.request.post(process.env.VITE_SUPABASE_URL + '/rest/v1/rpc/apply_command', {
    headers: { apikey: process.env.VITE_SUPABASE_ANON_KEY, Authorization: 'Bearer ' + session.access_token },
    data: { p_id: crypto.randomUUID(), p_command: { type: 'employee.salary', payload: { id: crypto.randomUUID(), salary: 1 } } },
  });
  assert.notEqual(salary.status(), 200);
  assert.match((await salary.json()).message, /administrateur/);
  await page.getByLabel('Rôle de ' + manager.name, { exact: true }).selectOption('pending');
  await page.getByRole('button', { name: 'Confirmer les droits', exact: true }).click();
  await page.getByRole('row').filter({ hasText: manager.name }).getByText('Sans accès', { exact: true }).waitFor();
  await managerPage.reload();
  await managerPage.getByRole('button', { name: 'Se connecter', exact: true }).waitFor();
  assert.equal(await managerPage.getByRole('navigation').count(), 0);
  await page.getByLabel('Rôle de ' + manager.name, { exact: true }).selectOption('manager');
  await page.getByRole('button', { name: 'Confirmer les droits', exact: true }).click();
  await page.getByRole('row').filter({ hasText: manager.name }).getByText('Actif', { exact: true }).waitFor();
  await managerPage.getByRole('button', { name: 'Vérifier mon accès', exact: true }).click();
  await managerPage.getByRole('heading', { name: 'Bonjour,' }).waitFor({ timeout: 20000 });
  assert.deepEqual(errors, []);
  console.log(JSON.stringify({ adminLogin: true, managerCreatedThroughAdminUI: true, managerLogin: true, unauthorizedCreationBlocked: true, managerCreationBlocked: true, managerSalaryChangeBlocked: true, suspensionClearsCachedData: true, reactivation: true }));
} finally {
  // Restore the requested manager test role even if an assertion fails mid-suspension.
  if (manager.id) await service.from('profiles').update({ role: 'manager' }).eq('id', manager.id);
  await browser.close();
}
